// 教学简化模型，真实定义请对照项目的 AgentStreamEvent。
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.channelFlow
import kotlinx.coroutines.flow.collect
import kotlinx.coroutines.runBlocking

sealed interface DemoEvent {
    data object Started : DemoEvent
    data class TextDelta(val text: String) : DemoEvent
    data class Completed(val text: String) : DemoEvent
}

fun runDemo(): Flow<DemoEvent> = channelFlow {
    println("生产者开始")
    send(DemoEvent.Started)
    delay(300)
    send(DemoEvent.TextDelta("你好"))
    delay(300)
    send(DemoEvent.TextDelta("，Flow"))
    send(DemoEvent.Completed("你好，Flow"))
}

runBlocking {
    val events = runDemo()
    println("已拿到 Flow")
    delay(300)
    events.collect { event ->
        when (event) {
            DemoEvent.Started -> println("开始")
            is DemoEvent.TextDelta -> println("增量：${event.text}")
            is DemoEvent.Completed -> println("最终正文：${event.text}")
        }
    }
    println("收集结束")
}
